// DAILY SUGGESTION ENGINE
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Get the daily suggested ritual based on moon phase, horoscope themes, and time of day.
 */
export function getDailySuggestedRitual(
  moonPhase: string,
  horoscopeThemes?: string[],
  maxTier?: number,
): CatalogRitual {
  // Filter by tier if specified
  const tierPool = maxTier !== undefined
    ? RITUAL_CATALOG.filter((r) => (r.tier ?? 0) <= maxTier)
    : RITUAL_CATALOG;

  // Find rituals that match the current moon phase
  const phaseMatches = tierPool.filter((r) =>
    r.bestPhases.includes(moonPhase)
  );

  if (phaseMatches.length === 0) return tierPool[0] || RITUAL_CATALOG[0];

  // If we have horoscope themes, try to match by category
  if (horoscopeThemes && horoscopeThemes.length > 0) {
    const themeToCategory: Record<string, RitualCategory> = {
      love: "love", romance: "love", relationship: "love", partner: "love", heart: "love",
      career: "career", work: "career", job: "career", ambition: "career", success: "career",
      health: "health", body: "health", energy: "health", wellness: "health", rest: "health",
      money: "wealth", finance: "wealth", abundance: "wealth", wealth: "wealth", prosperity: "wealth",
      creative: "creativity", art: "creativity", expression: "creativity", inspiration: "creativity",
      protect: "protection", boundary: "protection", shield: "protection", safety: "protection",
      grow: "growth", learn: "growth", change: "growth", transform: "growth", evolve: "growth",
      peace: "peace", calm: "peace", anxiety: "peace", stress: "peace", serenity: "peace",
      clarity: "clarity", decision: "clarity", focus: "clarity", direction: "clarity",
      release: "release", letting: "release", forgive: "release", surrender: "release",
      manifest: "manifestation", attract: "manifestation", create: "manifestation", build: "manifestation",
    };

    for (const theme of horoscopeThemes) {
      const lower = theme.toLowerCase();
      for (const [keyword, category] of Object.entries(themeToCategory)) {
        if (lower.includes(keyword)) {
          const categoryMatches = phaseMatches.filter((r) => r.category === category);
          if (categoryMatches.length > 0) {
            const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0).getTime()) / 86400000);
            return categoryMatches[dayOfYear % categoryMatches.length];
          }
        }
      }
    }
  }

  // Fallback: pick based on day of year for variety
  const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0).getTime()) / 86400000);
  return phaseMatches[dayOfYear % phaseMatches.length];
}
