"use client";

/**
 * Ritual page — daily ritual suggestions + browseable catalog by life area.
 *
 * Sections:
 * 1. Today's Celestial Energy — moon phase, zodiac season, nakshatra
 * 2. Almanac Best Days — tappable icon grid by category
 * 3. Today's Ritual — one personalized suggestion based on horoscope + moon
 * 4. Ritual Catalog — browse by life area (love, career, health, wealth, etc.)
 * 5. Celestial Calendar — upcoming events
 */

import { useState, useMemo, useEffect } from "react";
import {
  getDailyEnergy,
  getCurrentNakshatra,
  getCelestialEvents,
  type CelestialEvent,
} from "@/lib/celestialCalendar";
import { getDailyRituals, type ModalityPrefs } from "@/lib/rituals";
import {
  RITUAL_CATALOG,
  RITUAL_CATEGORIES,
  getDailySuggestedRitual,
  type CatalogRitual,
  type RitualCategory,
} from "@/lib/ritualCatalog";
import { supabase } from "@/lib/supabase";

// ─── Constants ──────────────────────────────────────────────────────────────

const RITUAL_PREFS_KEY = "mapped:ritual-modalities";

const RITUAL_MODALITIES = [
  { id: "crystals", icon: "💎", label: "Crystals" },
  { id: "candle", icon: "🕯", label: "Candles" },
  { id: "oils", icon: "💧", label: "Oils" },
  { id: "rune", icon: "ᚱ", label: "Runes" },
  { id: "chakra", icon: "🧘", label: "Chakras" },
  { id: "flowers", icon: "🌸", label: "Herbs" },
  { id: "tarot", icon: "🃏", label: "Tarot" },
  { id: "colors", icon: "🎨", label: "Colors" },
] as const;

function loadRitualPrefs(): Record<string, boolean> {
  if (typeof window === "undefined") return {};
  try {
    const stored = localStorage.getItem(RITUAL_PREFS_KEY);
    if (stored) return JSON.parse(stored);
  } catch {}
  const defaults: Record<string, boolean> = {};
  RITUAL_MODALITIES.forEach((m) => (defaults[m.id] = true));
  return defaults;
}

const ELEMENT_ICONS: Record<string, string> = {
  fire: "🔥", water: "🌊", earth: "🌿", air: "💨", spirit: "✨",
};

const MOOD_LABELS: Record<string, string> = {
  calm: "Calming", energized: "Energizing", reflective: "Reflective",
  joyful: "Uplifting", grounded: "Grounding", releasing: "Releasing",
};

// ─── Celestial Calendar Components ──────────────────────────────────────────

function EventCard({ event, isToday }: { event: CelestialEvent; isToday: boolean }) {
  const d = event.date instanceof Date ? event.date : new Date(event.date + "T12:00:00");
  return (
    <div className={`flex gap-3 items-start py-3 border-b border-foreground/8 last:border-b-0 ${isToday ? "bg-terracotta/5 -mx-2 px-2 rounded-lg" : ""}`}>
      <div className="text-center min-w-[36px]">
        <p className="text-foreground/30 text-[9px] uppercase">{d.toLocaleDateString("en-US", { month: "short" })}</p>
        <p className={`text-[18px] font-bold ${isToday ? "text-terracotta" : "text-foreground/60"}`}>{d.getDate()}</p>
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-0.5">
          <p className="text-foreground/80 text-[13px] font-medium truncate">{event.name}</p>
          {isToday && <span className="text-[8px] bg-terracotta/15 text-terracotta px-1.5 py-0.5 rounded-full font-bold uppercase">Today</span>}
        </div>
        <p className="text-foreground/40 text-[11px] leading-relaxed line-clamp-2">{event.ritualHint}</p>
      </div>
    </div>
  );
}

// ─── Ritual Card Component ──────────────────────────────────────────────────

function RitualDetailCard({
  ritual,
  isExpanded,
  onToggle,
  variant = "default",
}: {
  ritual: CatalogRitual | { id: string; title: string; description: string; steps: string[]; mood: string; element: string; source?: string; isPersonalized?: boolean; duration?: string };
  isExpanded: boolean;
  onToggle: () => void;
  variant?: "default" | "featured";
}) {
  const isFeatured = variant === "featured";
  return (
    <div className={`rounded-2xl border transition-all ${
      isFeatured
        ? "bg-terracotta/6 border-terracotta/20"
        : "bg-white/40 border-foreground/10"
    }`}>
      <button onClick={onToggle} className="w-full text-left p-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[14px]">{ELEMENT_ICONS[ritual.element] || "✨"}</span>
              <h3 className="text-foreground/80 text-[14px] font-medium">{ritual.title}</h3>
            </div>
            <div className="flex items-center gap-2 text-[10px] flex-wrap">
              {(() => {
                // Cast once to avoid hydration mismatches from "in" operator checks
                const r = ritual as CatalogRitual & { source?: string; isPersonalized?: boolean };
                const tierLabel = r.tier === 0 ? "No tools" : r.tier === 1 ? "Household" : r.tier === 2 ? "Crystals" : r.tier === 3 ? "Full Practice" : r.tier === 4 ? "Advanced" : null;
                return (
                  <>
                    <span className={`px-1.5 py-0.5 rounded-full ${
                      isFeatured ? "bg-terracotta/15 text-terracotta" : "bg-foreground/5 text-foreground/40"
                    }`}>
                      {MOOD_LABELS[r.mood] || r.mood}
                    </span>
                    {r.duration && <span className="text-foreground/30">{r.duration}</span>}
                    {tierLabel && (
                      <span className="px-1.5 py-0.5 rounded-full bg-sage/15 text-sage font-medium">{tierLabel}</span>
                    )}
                    {r.signSpecific && (
                      <span className="px-1.5 py-0.5 rounded-full bg-purple/15 text-purple font-medium">{r.signSpecific}</span>
                    )}
                    {r.source && <span className="text-foreground/30">{r.source}</span>}
                    {r.isPersonalized && (
                      <span className="bg-amber/15 text-amber px-1.5 py-0.5 rounded-full font-bold">For You</span>
                    )}
                  </>
                );
              })()}
            </div>
          </div>
          <svg className={`w-4 h-4 text-foreground/25 transition-transform shrink-0 mt-1 ${isExpanded ? "rotate-90" : ""}`}
               fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path d="M9 18l6-6-6-6" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </div>
        {!isExpanded && (
          <p className="text-foreground/40 text-[12px] leading-relaxed mt-1.5 line-clamp-2">{ritual.description}</p>
        )}
      </button>

      {isExpanded && (
        <div className="px-4 pb-4 pt-0">
          <div className="border-t border-foreground/8 pt-3">
            <p className="text-foreground/55 text-[12px] leading-relaxed mb-4">{ritual.description}</p>

            {/* Tools needed */}
            {(() => {
              const r = ritual as CatalogRitual;
              return r.toolsNeeded && r.toolsNeeded.length > 0 ? (
                <div className="mb-4 p-2.5 rounded-xl bg-foreground/3">
                  <p className="text-foreground/40 text-[10px] uppercase tracking-wider font-semibold mb-1.5">You&apos;ll need</p>
                  <p className="text-foreground/55 text-[11px] leading-relaxed">{r.toolsNeeded.join(" · ")}</p>
                </div>
              ) : null;
            })()}

            {/* Best timing */}
            {(() => {
              const r = ritual as CatalogRitual;
              return r.bestTiming ? (
                <div className="mb-4 flex items-start gap-2">
                  <span className="text-[11px] mt-0.5">⏰</span>
                  <p className="text-foreground/45 text-[11px] italic">{r.bestTiming}</p>
                </div>
              ) : null;
            })()}

            {/* Steps */}
            <div className="space-y-3">
              {ritual.steps.map((step, i) => (
                <div key={i} className="flex gap-3">
                  <span className="text-terracotta/50 text-[11px] font-bold mt-0.5 shrink-0">{i + 1}</span>
                  <p className="text-foreground/65 text-[12px] leading-[1.7]">{step}</p>
                </div>
              ))}
            </div>

            {/* Affirmation */}
            {(ritual as CatalogRitual).affirmation && (
              <div className="mt-4 p-3 rounded-xl bg-terracotta/5 border border-terracotta/10">
                <p className="text-foreground/35 text-[9px] uppercase tracking-wider font-semibold mb-1">Affirmation to carry</p>
                <p className="text-foreground/70 text-[13px] italic leading-relaxed">&ldquo;{(ritual as CatalogRitual).affirmation}&rdquo;</p>
              </div>
            )}

            {/* After instructions */}
            {(ritual as CatalogRitual).afterInstructions && (
              <div className="mt-3">
                <p className="text-foreground/35 text-[9px] uppercase tracking-wider font-semibold mb-1">After</p>
                <p className="text-foreground/45 text-[11px] leading-relaxed">{(ritual as CatalogRitual).afterInstructions}</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Main Page ──────────────────────────────────────────────────────────────

export default function RitualPage() {
  const today = useMemo(() => new Date(), []);
  const todayStr = today.toISOString().slice(0, 10);

  const energy = useMemo(() => getDailyEnergy(today), [today]);
  const nakshatra = useMemo(() => getCurrentNakshatra(today), [today]);
  const events = useMemo(() => getCelestialEvents(today.getFullYear()), [today]);

  const [ritualModPrefs] = useState<ModalityPrefs>(loadRitualPrefs);
  const [chartInfo, setChartInfo] = useState<{ sunSign?: string; moonSign?: string; risingSign?: string }>({});

  const rituals = useMemo(
    () => getDailyRituals(today, chartInfo, ritualModPrefs),
    [today, chartInfo, ritualModPrefs]
  );

  // ─── "My Tools" drawer — toggleable tool categories ───
  const TOOL_OPTIONS = [
    { id: "candles", icon: "🕯️", label: "Candles", desc: "Any color candle" },
    { id: "salt", icon: "🧂", label: "Salt", desc: "Sea salt or Epsom" },
    { id: "herbs", icon: "🌿", label: "Kitchen Herbs", desc: "Cinnamon, rosemary, bay, lavender" },
    { id: "bath", icon: "🛁", label: "Bathtub", desc: "For ritual baths and soaks" },
    { id: "mirror", icon: "🪞", label: "Mirror", desc: "Any mirror you can sit in front of" },
    { id: "rose-quartz", icon: "💗", label: "Rose Quartz", desc: "Love and self-love" },
    { id: "clear-quartz", icon: "🤍", label: "Clear Quartz", desc: "Clarity and amplification" },
    { id: "amethyst", icon: "💜", label: "Amethyst", desc: "Peace and intuition" },
    { id: "incense", icon: "🪔", label: "Incense", desc: "Frankincense, sandalwood, palo santo" },
    { id: "crystals-other", icon: "💎", label: "Other Crystals", desc: "Citrine, black tourmaline, selenite, etc." },
    { id: "oils", icon: "💧", label: "Essential Oils", desc: "For anointing and scent" },
    { id: "tarot", icon: "🃏", label: "Tarot / Oracle Deck", desc: "For card-based rituals" },
  ] as const;

  const [myTools, setMyTools] = useState<Record<string, boolean>>({});
  const [showToolDrawer, setShowToolDrawer] = useState(false);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("mapped:my-tools");
      if (saved) setMyTools(JSON.parse(saved));
    } catch {}
  }, []);

  const toggleTool = (id: string) => {
    setMyTools((prev) => {
      const next = { ...prev, [id]: !prev[id] };
      try { localStorage.setItem("mapped:my-tools", JSON.stringify(next)); } catch {}
      return next;
    });
  };

  const enabledToolCount = Object.values(myTools).filter(Boolean).length;

  // Catalog state
  const [selectedCategory, setSelectedCategory] = useState<RitualCategory | null>(null);
  const [expandedRitual, setExpandedRitual] = useState<string | null>(null);
  const [expandedCatalogRitual, setExpandedCatalogRitual] = useState<string | null>(null);

  // Almanac state
  const [openAlmanacCategory, setOpenAlmanacCategory] = useState<string | null>(null);

  // Calendar
  const [showAllEvents, setShowAllEvents] = useState(false);

  // Load chart info
  useEffect(() => {
    async function loadChart() {
      try {
        const cached = sessionStorage.getItem("mapped:chart-bigthree");
        if (cached) { setChartInfo(JSON.parse(cached)); return; }
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.user) return;
        const { data: chart } = await supabase.from("charts").select("big_three").eq("user_id", session.user.id).order("created_at", { ascending: false }).limit(1).maybeSingle();
        if (chart?.big_three) {
          const bt = chart.big_three as { sun?: string; moon?: string; rising?: string };
          setChartInfo({ sunSign: bt.sun, moonSign: bt.moon, risingSign: bt.rising });
          try { sessionStorage.setItem("mapped:chart-bigthree", JSON.stringify({ sunSign: bt.sun, moonSign: bt.moon, risingSign: bt.rising })); } catch {}
        }
      } catch {}
    }
    loadChart();
  }, []);

  // Map tool IDs to keywords that appear in ritual toolsNeeded arrays
  const toolKeywords: Record<string, string[]> = useMemo(() => ({
    "candles": ["candle"],
    "salt": ["salt"],
    "herbs": ["herb", "cinnamon", "rosemary", "bay", "lavender", "peppermint"],
    "bath": ["bath", "tub"],
    "mirror": ["mirror"],
    "rose-quartz": ["rose quartz"],
    "clear-quartz": ["clear quartz"],
    "amethyst": ["amethyst"],
    "incense": ["incense", "frankincense", "sandalwood", "palo santo"],
    "crystals-other": ["citrine", "black tourmaline", "selenite", "carnelian", "lapis", "crystal"],
    "oils": ["oil"],
    "tarot": ["tarot", "oracle"],
  }), []);

  // Check if user has the tools needed for a ritual
  const userHasToolsFor = useMemo(() => {
    return (ritual: CatalogRitual): boolean => {
      if (!ritual.toolsNeeded || ritual.toolsNeeded.length === 0) return true;
      const needed = ritual.toolsNeeded.join(" ").toLowerCase();
      // Check each tool category — if something in the ritual matches a category the user hasn't toggled on, exclude it
      for (const [toolId, keywords] of Object.entries(toolKeywords)) {
        if (myTools[toolId]) continue; // user has this, skip
        // If any keyword from this tool category appears in the needed tools, the user is missing something
        for (const kw of keywords) {
          if (needed.includes(kw)) return false;
        }
      }
      return true;
    };
  }, [myTools, toolKeywords]);

  // Filter catalog by user's tools
  const toolFilteredCatalog = useMemo(
    () => RITUAL_CATALOG.filter(userHasToolsFor),
    [userHasToolsFor]
  );

  // Daily suggested ritual (respects tool filter)
  const dailySuggestion = useMemo(
    () => {
      const pool = toolFilteredCatalog.length > 0 ? toolFilteredCatalog : RITUAL_CATALOG;
      const phaseMatches = pool.filter((r) => r.bestPhases.includes(energy.moonPhase.phase));
      if (phaseMatches.length === 0) return pool[0];
      const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0).getTime()) / 86400000);
      return phaseMatches[dayOfYear % phaseMatches.length];
    },
    [energy.moonPhase.phase, toolFilteredCatalog]
  );

  // Filtered catalog rituals (category + tools)
  const filteredRituals = useMemo(
    () => selectedCategory ? toolFilteredCatalog.filter((r) => r.category === selectedCategory) : toolFilteredCatalog,
    [selectedCategory, toolFilteredCatalog]
  );

  // Upcoming events (next 30 days)
  const upcomingEvents = useMemo(() => {
    const endDate = new Date(today);
    endDate.setDate(endDate.getDate() + 30);
    return events.filter((e) => e.date >= today && e.date <= endDate).slice(0, showAllEvents ? 30 : 5);
  }, [events, today, showAllEvents]);

  // Nakshatra suggestion
  const nakshatraSuggestions: Record<string, string> = {
    "Swift": "Move fast today — decisions and actions flow better without overthinking.",
    "Creative": "Make something. Your creative channel is wide open.",
    "Purifying": "Clean something — your space, your mind, a relationship.",
    "Nurturing": "Feed someone, including yourself. Lush, fertile energy.",
    "Searching": "Follow your curiosity. The question matters more than the answer.",
    "Stormy": "If emotions rise, let them. Something needs to break through.",
    "Renewing": "Try again. Whatever you gave up on might have a second chance.",
    "Nourishing": "Most auspicious day in Vedic astrology. Invest and commit.",
    "Mystical": "Trust your instincts. Good for divination and dream work.",
    "Royal": "Claim your space. Connect with your ancestors.",
    "Joyful": "Rest and play. The universe gives you permission to enjoy.",
    "Friendly": "Reach out to someone. Good for alliances and asking for support.",
    "Skillful": "Work with your hands. Extra care in what you craft today.",
    "Brilliant": "Beauty and design are favored. Trust your aesthetic instincts.",
    "Independent": "Do your own thing. Flexibility is rewarded.",
    "Determined": "Lock in on one goal and push. Extra willpower available.",
    "Devotional": "Deepen a bond. Show up fully. Loyalty is rewarded.",
    "Protective": "Stand up for what's right. Leadership energy is strong.",
    "Uprooting": "Get to the root of something. Shadow work is favored.",
    "Invincible": "Start something serious. Momentum will carry you.",
    "Universal": "Play the long game. Patient, ethical action wins.",
    "Listening": "Be quiet and listen. The universe has something to say.",
    "Rhythmic": "Find your groove. Music, dance, and financial moves favored.",
    "Healing": "Solitude heals today. Retreat if you can.",
    "Intense": "Go bold in your spiritual practice. Break through the stuck.",
    "Deep": "Meditate. Deepest wisdom comes from stillness.",
    "Gentle": "Wrap things up gracefully. A day for gentle endings.",
  };

  const dateStr = today.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });

  return (
    <main className="flex-1 flex flex-col px-5 py-6 max-w-lg mx-auto w-full pb-28">

      {/* ─── HEADER with tools icon ─── */}
      <div className="flex items-center justify-between mb-1">
        <h1 className="text-2xl text-foreground" style={{ fontFamily: "'Ahsing', 'Playfair Display', serif" }}>
          Ritual
        </h1>
        <button
          onClick={() => setShowToolDrawer(true)}
          className="relative flex items-center gap-1.5 px-3 py-2 rounded-xl bg-white/50 border border-foreground/10 active:scale-95 transition-all"
        >
          <svg className="w-4 h-4 text-foreground/40" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
            <path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.066 2.573c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.573 1.066c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.066-2.573c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" strokeLinecap="round" strokeLinejoin="round" />
            <circle cx="12" cy="12" r="3" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span className="text-foreground/40 text-[11px] font-medium">My Tools</span>
        </button>
      </div>
      <p className="text-foreground/40 text-sm mb-6">
        {dateStr}
      </p>

      {/* ─── My Tools Slide-Over Drawer ─── */}
      {showToolDrawer && (
        <div className="fixed inset-0 z-50 flex justify-end">
          {/* Backdrop */}
          <div
            className="absolute inset-0 bg-black/30 backdrop-blur-sm"
            onClick={() => setShowToolDrawer(false)}
          />
          {/* Drawer */}
          <div className="relative w-[85%] max-w-sm bg-[#f5f0ea] h-full overflow-y-auto shadow-2xl animate-in slide-in-from-right duration-200">
            {/* Header */}
            <div className="sticky top-0 bg-[#f5f0ea] z-10 px-5 pt-6 pb-4 border-b border-foreground/8">
              <div className="flex items-center justify-between mb-1">
                <h2 className="text-foreground/80 text-[18px] font-semibold" style={{ fontFamily: "'Ahsing', 'Playfair Display', serif" }}>
                  My Tools
                </h2>
                <button
                  onClick={() => setShowToolDrawer(false)}
                  className="w-8 h-8 flex items-center justify-center rounded-full bg-foreground/5 active:bg-foreground/10"
                >
                  <svg className="w-4 h-4 text-foreground/40" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                    <path d="M6 18L18 6M6 6l12 12" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                </button>
              </div>
              <p className="text-foreground/40 text-[12px] leading-relaxed">
                Toggle on the tools you have. We&apos;ll only suggest rituals that match what you own.
              </p>
            </div>

            {/* Tool toggles */}
            <div className="px-5 py-4">
              {/* Always available (no toggle needed) */}
              <div className="mb-5">
                <p className="text-foreground/30 text-[9px] uppercase tracking-widest font-semibold mb-2">Always available</p>
                <div className="flex flex-wrap gap-2">
                  {["Body", "Breath", "Voice", "Water", "Paper & Pen", "Walking"].map((t) => (
                    <span key={t} className="px-2.5 py-1.5 rounded-lg bg-sage/10 text-sage text-[10px] font-medium">{t}</span>
                  ))}
                </div>
              </div>

              {/* Household */}
              <div className="mb-5">
                <p className="text-foreground/30 text-[9px] uppercase tracking-widest font-semibold mb-3">Household</p>
                <div className="space-y-1">
                  {TOOL_OPTIONS.filter((t) => ["candles", "salt", "herbs", "bath", "mirror"].includes(t.id)).map((tool) => (
                    <button
                      key={tool.id}
                      onClick={() => toggleTool(tool.id)}
                      className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all active:scale-[0.98] ${
                        myTools[tool.id]
                          ? "bg-sage/8 border-sage/20"
                          : "bg-white/30 border-foreground/6"
                      }`}
                    >
                      <span className="text-[18px] w-7 text-center">{tool.icon}</span>
                      <div className="flex-1 text-left">
                        <p className={`text-[13px] font-medium ${myTools[tool.id] ? "text-foreground/70" : "text-foreground/40"}`}>{tool.label}</p>
                        <p className="text-foreground/25 text-[10px]">{tool.desc}</p>
                      </div>
                      <div className={`w-10 h-6 rounded-full transition-all flex items-center ${
                        myTools[tool.id] ? "bg-sage justify-end" : "bg-foreground/10 justify-start"
                      }`}>
                        <div className={`w-5 h-5 rounded-full bg-white shadow-sm mx-0.5 transition-all`} />
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Crystals & Incense */}
              <div className="mb-5">
                <p className="text-foreground/30 text-[9px] uppercase tracking-widest font-semibold mb-3">Crystals &amp; Incense</p>
                <div className="space-y-1">
                  {TOOL_OPTIONS.filter((t) => ["rose-quartz", "clear-quartz", "amethyst", "incense", "crystals-other"].includes(t.id)).map((tool) => (
                    <button
                      key={tool.id}
                      onClick={() => toggleTool(tool.id)}
                      className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all active:scale-[0.98] ${
                        myTools[tool.id]
                          ? "bg-sage/8 border-sage/20"
                          : "bg-white/30 border-foreground/6"
                      }`}
                    >
                      <span className="text-[18px] w-7 text-center">{tool.icon}</span>
                      <div className="flex-1 text-left">
                        <p className={`text-[13px] font-medium ${myTools[tool.id] ? "text-foreground/70" : "text-foreground/40"}`}>{tool.label}</p>
                        <p className="text-foreground/25 text-[10px]">{tool.desc}</p>
                      </div>
                      <div className={`w-10 h-6 rounded-full transition-all flex items-center ${
                        myTools[tool.id] ? "bg-sage justify-end" : "bg-foreground/10 justify-start"
                      }`}>
                        <div className={`w-5 h-5 rounded-full bg-white shadow-sm mx-0.5 transition-all`} />
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Advanced */}
              <div className="mb-5">
                <p className="text-foreground/30 text-[9px] uppercase tracking-widest font-semibold mb-3">Advanced</p>
                <div className="space-y-1">
                  {TOOL_OPTIONS.filter((t) => ["oils", "tarot"].includes(t.id)).map((tool) => (
                    <button
                      key={tool.id}
                      onClick={() => toggleTool(tool.id)}
                      className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl border transition-all active:scale-[0.98] ${
                        myTools[tool.id]
                          ? "bg-sage/8 border-sage/20"
                          : "bg-white/30 border-foreground/6"
                      }`}
                    >
                      <span className="text-[18px] w-7 text-center">{tool.icon}</span>
                      <div className="flex-1 text-left">
                        <p className={`text-[13px] font-medium ${myTools[tool.id] ? "text-foreground/70" : "text-foreground/40"}`}>{tool.label}</p>
                        <p className="text-foreground/25 text-[10px]">{tool.desc}</p>
                      </div>
                      <div className={`w-10 h-6 rounded-full transition-all flex items-center ${
                        myTools[tool.id] ? "bg-sage justify-end" : "bg-foreground/10 justify-start"
                      }`}>
                        <div className={`w-5 h-5 rounded-full bg-white shadow-sm mx-0.5 transition-all`} />
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Summary */}
              <div className="rounded-xl bg-white/40 border border-foreground/8 p-3 mt-2">
                <p className="text-foreground/35 text-[11px] leading-relaxed">
                  {enabledToolCount === 0
                    ? "No tools selected — you'll see rituals that use only your body, breath, and a pen."
                    : `${enabledToolCount} tool${enabledToolCount === 1 ? "" : "s"} selected — ${toolFilteredCatalog.length} ritual${toolFilteredCatalog.length === 1 ? "" : "s"} available for you.`
                  }
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════
          ═══  TODAY'S RITUAL (single card)  ═══
          ═══════════════════════════════════════ */}
      <div className="mb-6">
        <h2 className="text-foreground/80 text-[11px] uppercase tracking-[0.2em] font-semibold mb-3">
          Today&apos;s Ritual
        </h2>

        <RitualDetailCard
          ritual={dailySuggestion}
          isExpanded={expandedRitual === dailySuggestion.id}
          onToggle={() => setExpandedRitual(expandedRitual === dailySuggestion.id ? null : dailySuggestion.id)}
          variant="featured"
        />
      </div>

      {/* ═══════════════════════════════════════
          ═══  TODAY'S ENERGY  ═══
          ═══════════════════════════════════════ */}

      {/* Moon Phase + Nakshatra */}
      <div className="rounded-2xl bg-white/50 border border-foreground/12 p-5 mb-4">
        <div className="flex items-center gap-4">
          <div className="text-center">
            <span className="text-[40px]">{energy.moonPhase.emoji}</span>
          </div>
          <div className="flex-1">
            <h2 className="text-foreground/80 text-[15px] font-medium">{energy.moonPhase.label}</h2>
            <p className="text-foreground/40 text-[11px]">
              {Math.round(energy.moonPhase.illumination)}% illuminated · {energy.zodiacSeason.sign} season
            </p>
            <p className="text-foreground/50 text-[12px] leading-relaxed mt-1.5">
              {energy.moonPhase.energy}
            </p>
          </div>
        </div>

        {/* Nakshatra insight */}
        <div className="mt-3 pt-3 border-t border-foreground/8">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-[10px] text-amber/70 font-bold uppercase tracking-wider">Nakshatra</span>
            <span className="text-foreground/60 text-[12px] font-medium">{nakshatra.name}</span>
            <span className="text-foreground/30 text-[10px]">({nakshatra.quality})</span>
          </div>
          <p className="text-foreground/45 text-[11px] leading-relaxed">
            {nakshatraSuggestions[nakshatra.quality] || "Trust the flow of the day."}
          </p>
        </div>
      </div>

      {/* ═══════════════════════════════════════
          ═══  ALMANAC BEST DAYS  ═══
          ═══════════════════════════════════════ */}
      <div className="rounded-2xl bg-[#7a8c6e]/8 border border-[#7a8c6e]/15 p-4 mb-6">
        <div className="flex items-center gap-2 mb-1.5">
          <span className="text-sm">🌾</span>
          <span className="text-[10px] text-sage uppercase tracking-widest font-semibold">Almanac</span>
        </div>
        <p className="text-foreground/45 text-[11px] leading-relaxed mb-3">
          Best days guidance for the {energy.moonPhase.label.toLowerCase()}. Tap to see details.
        </p>

        {/* Category icon grid */}
        <div className="grid grid-cols-3 gap-2 mb-3">
          {[
            { category: "Garden", icon: "🌱", tip: `${energy.moonPhase.almanac.gardening} Best for: ${energy.moonPhase.almanac.bestFor.join(", ")}. Avoid: ${energy.moonPhase.almanac.avoid.join(", ")}.` },
            ...energy.moonPhase.almanac.lifeTips,
          ].map((tip) => (
            <button
              key={tip.category}
              onClick={() => setOpenAlmanacCategory(openAlmanacCategory === tip.category ? null : tip.category)}
              className={`flex flex-col items-center gap-1.5 py-3 px-1 rounded-xl border transition-all active:scale-[0.96]
                ${openAlmanacCategory === tip.category
                  ? "bg-sage/15 border-sage/30"
                  : "bg-white/40 border-foreground/8 hover:bg-white/60"
                }`}
            >
              <span className="text-[20px]">{tip.icon}</span>
              <span className={`text-[9px] font-semibold leading-tight text-center ${
                openAlmanacCategory === tip.category ? "text-sage" : "text-foreground/45"
              }`}>
                {tip.category}
              </span>
            </button>
          ))}
        </div>

        {/* Expanded category detail */}
        {openAlmanacCategory && (() => {
          const allTips = [
            { category: "Garden", icon: "🌱", tip: `${energy.moonPhase.almanac.gardening} Best for: ${energy.moonPhase.almanac.bestFor.join(", ")}. Avoid: ${energy.moonPhase.almanac.avoid.join(", ")}.` },
            ...energy.moonPhase.almanac.lifeTips,
          ];
          const tip = allTips.find((t) => t.category === openAlmanacCategory);
          if (!tip) return null;
          return (
            <div className="rounded-xl bg-white/50 border border-sage/15 p-4 mb-2 animate-in fade-in slide-in-from-top-2 duration-200">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-[16px]">{tip.icon}</span>
                <h4 className="text-foreground/80 text-[13px] font-semibold">{tip.category}</h4>
                <span className="ml-auto px-2 py-0.5 rounded-full bg-sage/10 text-sage text-[9px] font-bold uppercase">
                  {energy.moonPhase.label}
                </span>
              </div>
              <p className="text-foreground/65 text-[12px] leading-[1.7]">{tip.tip}</p>
            </div>
          );
        })()}

        <p className="text-foreground/30 text-[10px] leading-relaxed italic px-1">
          &ldquo;{energy.moonPhase.almanac.folkWisdom}&rdquo;
        </p>
      </div>

      {/* ═══════════════════════════════════════
          ═══  RITUAL CATALOG  ═══
          ═══════════════════════════════════════ */}
      <div className="mb-6">
        <h2 className="text-foreground/80 text-[11px] uppercase tracking-[0.2em] font-semibold mb-3">
          Browse Rituals
        </h2>

        {/* Category filter icons */}
        <div className="flex gap-2 overflow-x-auto scrollbar-none -mx-1 px-1 mb-4 pb-1">
          <button
            onClick={() => setSelectedCategory(null)}
            className={`shrink-0 px-3 py-2 rounded-xl text-[11px] font-semibold border transition-all ${
              selectedCategory === null
                ? "bg-terracotta/12 border-terracotta/25 text-terracotta"
                : "bg-white/30 border-foreground/8 text-foreground/40"
            }`}
          >
            All
          </button>
          {RITUAL_CATEGORIES.map((cat) => (
            <button
              key={cat.key}
              onClick={() => setSelectedCategory(selectedCategory === cat.key ? null : cat.key)}
              className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-xl text-[11px] font-semibold border transition-all ${
                selectedCategory === cat.key
                  ? "bg-terracotta/12 border-terracotta/25 text-terracotta"
                  : "bg-white/30 border-foreground/8 text-foreground/40"
              }`}
            >
              <span className="text-[13px]">{cat.icon}</span>
              {cat.label}
            </button>
          ))}
        </div>

        {/* Ritual list */}
        <div className="space-y-2">
          {filteredRituals.map((ritual) => (
            <RitualDetailCard
              key={ritual.id}
              ritual={ritual}
              isExpanded={expandedCatalogRitual === ritual.id}
              onToggle={() => setExpandedCatalogRitual(expandedCatalogRitual === ritual.id ? null : ritual.id)}
            />
          ))}
        </div>
      </div>

      {/* ═══════════════════════════════════════
          ═══  CELESTIAL CALENDAR  ═══
          ═══════════════════════════════════════ */}
      <div className="mb-6">
        <h2 className="text-foreground/80 text-[11px] uppercase tracking-[0.2em] font-semibold mb-3">
          Celestial Calendar
        </h2>

        <div className="rounded-2xl bg-white/40 border border-foreground/10 px-4 py-2">
          {upcomingEvents.map((event) => (
            <EventCard key={event.id} event={event} isToday={event.date.toISOString().slice(0, 10) === todayStr} />
          ))}

          {!showAllEvents && upcomingEvents.length >= 5 && (
            <button
              onClick={() => setShowAllEvents(true)}
              className="w-full py-3 text-terracotta text-[12px] font-medium hover:text-terracotta/80 transition-colors"
            >
              Show more events
            </button>
          )}
        </div>
      </div>

      {/* Quick energy footer */}
      <div className="flex gap-2 overflow-x-auto scrollbar-none -mx-1 px-1 pb-4">
        <div className="shrink-0 rounded-xl bg-white/40 border border-foreground/10 px-3 py-2">
          <p className="text-[9px] text-foreground/30 uppercase tracking-wider">{energy.dayOfWeek.planet}&apos;s day</p>
          <p className="text-foreground/55 text-[11px] font-medium">{energy.dayOfWeek.energy}</p>
        </div>
        <div className="shrink-0 rounded-xl bg-white/40 border border-foreground/10 px-3 py-2">
          <p className="text-[9px] text-foreground/30 uppercase tracking-wider">{energy.zodiacSeason.element} season</p>
          <p className="text-foreground/55 text-[11px] font-medium">{energy.zodiacSeason.theme}</p>
        </div>
      </div>
    </main>
  );
}
